from pathlib import Path
import json,html
p=Path(__file__).parent;s=json.loads((p/'status.json').read_text())
def tex(x):
 x=x.replace('→',' -> ').replace('≤',' <= ').replace('!=', ' != ').replace('’',"'")
 return ''.join({'\\':r'\textbackslash{}','&':r'\&','%':r'\%','$':r'\$','#':r'\#','_':r'\_','{':r'\{','}':r'\}','~':r'\textasciitilde{}','^':r'\textasciicircum{}'}.get(c,c) for c in x)
lines=[r'\documentclass[10pt]{article}',r'\usepackage[margin=0.7in]{geometry}',r'\usepackage[T1]{fontenc}',r'\usepackage{hyperref}',r'\usepackage{longtable}',r'\usepackage{array}',r'\hypersetup{colorlinks=true,urlcolor=blue}',r'\begin{document}',r'\sloppy',r'\section*{Collector transition and exceptional-branch source audit}',tex('Source inspection only. Eight transition obligations and eight ordered dispatch regions. No scientific execution, new measurements, or Lean replay. Existing component results are mapped to remaining composition obligations; no theorem is promoted by this report.'),r'\paragraph{Central invariant}',tex('The next composition target is decoded state d = aP + bQ in the Jacobian class group. Canonicality and Mumford polynomial validity are separate representation facts. Both trial candidates may insert relations, while only the selected candidate advances the walk.'),r'\paragraph{Source aliases}',tex('collector: retained projective_state_collector.rs; law: retained projective_law_gate.rs; three_leads: current repository src/cryptanalysis/three_leads.rs. Complete paths and hashes are listed at the end and in status.json.')]
for title,key,label in [('Collector transitions','transitions','transition'),('Ordered dispatch regions','branches','branch')]:
 lines += [r'\section*{'+title+'}']
 for i,row in enumerate(s[key],1):
  lines += [r'\subsection*{'+str(i)+'. '+tex(row[label])+'}',r'\textbf{Source:} '+tex(row['source'])+r'\par',r'\textbf{Existing evidence:} '+tex(row['existing_evidence'])+r'\par',r'\textbf{Remaining composition:} '+tex(row['remaining_composition'])+r'\par']
lines += [r'\section*{Interpretation and boundaries}',tex('A graph-label proof may use a homomorphism h from the Jacobian group into Z/r with h(P)=1 and h(Q)=k. Individual factor points need not each be r-torsion if that homomorphism is established. Its existence and normalization remain proof obligations. Native expect calls make mixed/degree-two None exclusions concrete panic-freedom conditions. Raw projective equality governs scheduling and deduplication; it must not silently mean canonical class equality.'),r'\par',tex(s['review_scope_note']),r'\section*{Bound source and evidence files}']
for path,digest in s['source_hashes'].items():
 lines += [r'\noindent\url{'+path+r'}\par',r'{\scriptsize\texttt{'+digest+r'}}\par\medskip']
lines += [r'\end{document}'];(p/'report.tex').write_text('\n'.join(lines)+'\n')
# Editable vector diagram: fixed topology, no measured quantities.
nodes=[(40,60,'Transfer / normalization','Shape, canonicality, class image'),(400,60,'Initialize / restart','d = aP + bQ; labelled jumps'),(40,200,'Two candidate additions','Each nd has matching na, nb'),(400,200,'Ordered branch dispatch','8 regions; None exclusions'),(40,340,'Split / signed physical row','Root multiplicity and sign'),(400,340,'Graph insertion','Potential and anchor invariant'),(40,480,'Choose continuation','Commit matching state + labels'),(400,480,'Scalar constraint','h(P)=1; h(Q)=k; unit denominator')]
svg=['<svg xmlns="http://www.w3.org/2000/svg" width="780" height="630" viewBox="0 0 780 630">','<rect width="780" height="630" fill="white"/>','<style>text{font-family:Arial,sans-serif;fill:#14283f}.title{font-size:18px;font-weight:bold}.body{font-size:13px}.small{font-size:12px}</style>','<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3z" fill="#4b647c"/></marker></defs>','<text x="30" y="28" class="title">Collector invariant composition map</text>']
for x1,y1,x2,y2 in [(340,100,400,100),(550,140,190,200),(340,240,400,240),(190,280,190,340),(340,380,400,380),(190,420,190,480),(550,420,550,480),(190,480,190,280)]:svg += [f'<path d="M{x1},{y1} L{x2},{y2}" stroke="#4b647c" stroke-width="1.5" fill="none" marker-end="url(#arrow)"/>']
for x,y,t,b in nodes:svg += [f'<rect x="{x}" y="{y}" width="300" height="80" rx="8" fill="#edf4f8" stroke="#5e7a93"/>',f'<text x="{x+12}" y="{y+28}" class="body" font-weight="bold">{html.escape(t)}</text>',f'<text x="{x+12}" y="{y+53}" class="small">{html.escape(b)}</text>']
svg += ['<text x="30" y="595" class="small">Source obligation map only. Arrows identify composition dependencies, not proved closure.</text>','<text x="30" y="615" class="small">Eight transitions and eight dispatch regions are detailed in status.json and report.pdf.</text>','</svg>'];(p/'flow.svg').write_text('\n'.join(svg)+'\n')
